SELECT ur.user_id, r.id AS role_id, r.role_code, r.role_name, r.role_type FROM system_user_role ur INNER JOIN system_role r ON r.id = ur.role_id WHERE ur.user_id IN
#{userId}
ORDER BY r.sort_order ASC, r.id ASC

SELECT DISTINCT ur.user_id FROM system_user_role ur INNER JOIN system_role r ON r.id = ur.role_id WHERE ur.user_id IN
#{userId}
AND r.role_type = 'SYSTEM'

SELECT user_id FROM system_user_role WHERE user_id IN
#{userId}
GROUP BY user_id HAVING COUNT(*) = 1 AND MAX(role_id) = #{roleId}
